    renderers.py — Decorator Pattern으로 섹션 렌더러 자동 등록


        renderers.py — Decorator Pattern (신규)
        # [1] 렌더러 레지스트리: 타입명 → 함수 매핑
RENDERERS = {}

def renderer(section_type):                     # [2]
    """섹션 타입을 키로 렌더러 함수를 자동 등록하는 데코레이터"""
    def decorator(func):
        RENDERERS[section_type] = func
        return func
    return decorator

@renderer("title_block")                        # [3]
def render_title_block(doc, data):
    doc.set_font(size=18, bold=True)
    doc.insert_text(data["title"])
    if data.get("subtitle"):
        doc.set_font(size=11, color=Colors.GRAY)
        doc.insert_text(data["subtitle"])

@renderer("kv_table")                           # [4]
def render_kv_table(doc, data):
    rows = data["rows"]  # [["key", "value"], ...]
    doc.insert_table(len(rows), 2)
    for i, (k, v) in enumerate(rows):
        doc.fill_cell(i, 0, k, bold=True)
        doc.fill_cell(i, 1, v)

def render_section(doc, section):               # [5]
    fn = RENDERERS.get(section["type"])
    if fn:
        fn(doc, section["data"])

          [1] 전역 딕셔너리 RENDERERS가 모든 섹션 타입의 렌더 함수를 보관. 새 타입 추가 시 if/elif 체인 불필요.
          [2] @renderer("type") 데코레이터: 함수 정의 시점에 자동으로 레지스트리에 등록. Open-Closed Principle 준수.
          [3] 각 @renderer 함수는 (doc, data) 시그니처를 공유하여 통일된 인터페이스 유지.
          [4] kv_table: JSON의 rows 배열을 HWP 2열 테이블로 자동 변환. 행 수에 제한 없음.
          [5] render_section(): 진입점 함수. 레지스트리 조회 → 매칭된 렌더러 호출. 미등록 타입은 무시(graceful skip).
